-- 찾는 도구를 만든다

@Component
class SelfCallScanner implements InitializingBean {

    @Override
    public void afterPropertiesSet() throws Exception {
        int n = 0;
        for (String name : ctx.getBeanDefinitionNames()) {
            Class<?> t = AopUtils.getTargetClass(ctx.getBean(name));
            if (!t.getName().startsWith("study.adv")) continue;
            if (!AopUtils.isAopProxy(ctx.getBean(name))) continue;
            for (String[] call : scanInvokeVirtualOnThis(t)) {
                log.warn("자기 호출 {}.{} -> {}", t.getSimpleName(), call[0], call[1]);
                n++;
            }
        }
        log.warn("자기 호출 {} 곳", n);
    }
}

