-- 걸려야 할 것만 센다

@Component
class SelfCallScanner {
    boolean shouldMatch(Class<?> t, String method) {
        Method m = ReflectionUtils.findMethod(t, method);
        for (Advisor a : advisors)
            if (a instanceof PointcutAdvisor pa
                && pa.getPointcut().getMethodMatcher().matches(m, t)) return true;
        return false;
    }
}

